-- conservés.
-- =============================================================================

INSERT INTO charte_edition (che_code, che_libelle, che_contenu, che_defaut, che_modifie_par) VALUES
 ('DEFAUT', 'Charte LogiBTP', '{"police":"Inter","couleurs":{"texte":"#1f2328","discret":"#5f6b7a","primaire":"#1f4e79","secondaire":"#2e7d32","alerte":"#b42318","trait":"#9aa4b2","trait_fort":"#1f2328","fond_entete":"#e8eef5","fond_section":"#dfe7f1","fond_titre":"#f2f5f9","fond_total":"#e8eef5","blanc":"#ffffff","filigrane":"#d0d5dd"},"styles":{"normal":{"police":"Inter","taille":9,"graisse":400,"couleur":"texte","interligne":1.25},"petit":{"base":"normal","taille":7.5},"discret":{"base":"petit","couleur":"discret"},"gras":{"base":"normal","graisse":700},"titre":{"base":"normal","taille":16,"graisse":700,"couleur":"primaire"},"sous_titre":{"base":"normal","taille":11,"graisse":600,"couleur":"primaire"},"entete_tableau":{"base":"normal","taille":8,"graisse":600,"couleur":"texte"},"section":{"base":"normal","taille":10,"graisse":700,"couleur":"primaire"},"titre_ligne":{"base":"normal","graisse":600},"sous_total":{"base":"normal","graisse":600,"italique":true},"composante":{"base":"normal","taille":8,"couleur":"discret"},"montant":{"base":"normal","tnum":true},"total":{"base":"normal","graisse":700,"tnum":true},"nom_adresse":{"base":"normal","taille":10,"graisse":700},"mentions":{"base":"petit","taille":6.5,"couleur":"discret","interligne":1.2},"filigrane":{"base":"normal","taille":60,"graisse":700,"couleur":"filigrane"}},"traits":{"fin":{"epaisseur":0.15,"couleur":"trait"},"normal":{"epaisseur":0.3,"couleur":"trait"},"fort":{"epaisseur":0.5,"couleur":"trait_fort"},"primaire":{"epaisseur":0.5,"couleur":"primaire"}},"marges":{"haut":12,"bas":12,"gauche":12,"droite":12}}'::jsonb, TRUE, 'logibtp')
ON CONFLICT (che_code) DO NOTHING;

INSERT INTO modele_edition (med_code, med_libelle, med_genre, med_cible, med_source, med_types, med_contenu, med_niveau_acces, med_ordre, med_fourni, med_cree_par, med_modifie_par) VALUES
 ('ENTETE_SOCIETE', 'Entête : logo et coordonnées de la société', 'BLOC', NULL, NULL, '{}'::text[], '{"format_version":1,"code":"ENTETE_SOCIETE","libelle":"Entête : logo et coordonnées de la société","genre":"BLOC","parametres":[],"contenu":{"type":"pile","enfants":[{"type":"image","ressource":"LOGO","hauteur":18,"largeur":"45mm"},{"type":"champ","valeur":"{{societe.raison_sociale}}","style":"titre"},{"type":"repete","collection":"societe.adresse","contenu":{"type":"champ","valeur":"{{element}}"}},{"type":"champ","valeur":"=Joindre(\" – \"; Si(societe.telephone; \"Tél. \" & societe.telephone; Nul); societe.courriel)","style":"discret"}]}}'::jsonb, 'INTERNE', 0, TRUE, 'logibtp', 'logibtp'),
 ('COORDONNEES_DOCUMENT', 'Informations du document et destinataire', 'BLOC', NULL, NULL, '{}'::text[], '{"format_version":1,"code":"COORDONNEES_DOCUMENT","libelle":"Informations du document et destinataire","genre":"BLOC","parametres":[{"nom":"titre","defaut":""},{"nom":"libelle_adresse","defaut":"Adresse des travaux"}],"contenu":{"type":"rangee","espacement":6,"enfants":[{"type":"pile","largeur":"52%","fond":"fond_titre","marges":2.5,"enfants":[{"type":"champ","valeur":"=Si(bloc.titre; bloc.titre; document.type.libelle) & \" n° \" & Si(document.numero; document.numero; \"(brouillon)\")","style":"sous_titre"},{"type":"champ","valeur":"=Si(document.indice <> \"A\"; \"Indice \" & document.indice; Nul)","style":"discret"},{"type":"champ","valeur":"=Retrait(Gras(\"Date : \"); Date(document.date; \"long\"))"},{"type":"champ","valeur":"=Retrait(Gras(\"Situation n° : \"); document.avancement.rang)","condition":"document.avancement.rang"},{"type":"champ","valeur":"=Retrait(Gras(\"Validité : \"); document.validite_jours & \" jours, jusqu’au \" & Date(AjouterJours(document.date; document.validite_jours)))","condition":"document.validite_jours ET document.type.code = \"V_DEVIS\""},{"type":"champ","valeur":"=Retrait(Gras(\"Objet : \"); document.objet)","condition":"document.objet"},{"type":"champ","valeur":"=Retrait(Gras(\"Chantier : \"); Joindre(\" – \"; rattachement.chantier.code; rattachement.chantier.libelle))","condition":"rattachement.chantier"},{"type":"champ","valeur":"=Retrait(Gras(\"Marché : \"); Joindre(\" – \"; rattachement.marche.code; rattachement.marche.libelle))","condition":"rattachement.marche"},{"type":"champ","valeur":"=Retrait(Gras(\"Votre référence : \"); document.reference_externe)","condition":"document.reference_externe"},{"type":"champ","valeur":"=Retrait(Gras(\"Notre référence : \"); document.notre_reference)","condition":"document.notre_reference"},{"type":"champ","valeur":"=Retrait(Gras(\"Rédacteur : \"); redacteur.nom)","condition":"redacteur.nom"}]},{"type":"pile","largeur":"*","espacement":3,"enfants":[{"type":"pile","cadre":"fin","marges":3,"enfants":[{"type":"champ","valeur":"{{client.nom}}","style":"nom_adresse"},{"type":"champ","valeur":"{{client.contact}}"},{"type":"repete","collection":"client.adresse","contenu":{"type":"champ","valeur":"{{element}}"}},{"type":"champ","valeur":"{{client.courriel}}","style":"discret"},{"type":"champ","valeur":"=Si(client.tva; \"TVA : \" & client.tva; Nul)","style":"discret"}]},{"type":"pile","condition":"payeur.nom","marges":{"gauche":3},"enfants":[{"type":"champ","valeur":"Facturer à","style":"petit"},{"type":"champ","valeur":"{{payeur.nom}}","style":"gras"},{"type":"repete","collection":"payeur.adresse","contenu":{"type":"champ","valeur":"{{element}}"}}]},{"type":"pile","condition":"adresse_travaux","marges":{"gauche":3},"enfants":[{"type":"champ","valeur":"{{bloc.libelle_adresse}}","style":"petit"},{"type":"champ","valeur":"{{adresse_travaux.libelle}}","style":"gras"},{"type":"repete","collection":"adresse_travaux.adresse","contenu":{"type":"champ","valeur":"{{element}}"}},{"type":"champ","valeur":"=Joindre(\" – \"; adresse_travaux.contact; adresse_travaux.telephone)","style":"discret"},{"type":"champ","valeur":"{{adresse_travaux.instructions}}","style":"discret"}]}]}]}}'::jsonb, 'INTERNE', 0, TRUE, 'logibtp', 'logibtp'),
 ('LIGNES_DOCUMENT', 'Lignes du document (présentations : détaillée, sans composantes, sans prix, avancement)', 'BLOC', NULL, NULL, '{}'::text[], '{"format_version":1,"code":"LIGNES_DOCUMENT","libelle":"Lignes du document (présentations : détaillée, sans composantes, sans prix, avancement)","genre":"BLOC","parametres":[],"contenu":{"type":"tableau","nom":"lignes","collection":"lignes","remplir":true,"report":{"libelle":"Report","libelle_a_reporter":"À reporter"},"colonnes":[{"cle":"num","titre":"N°","largeur":"13mm","valeur":"{{ligne.numero}}","style":"petit"},{"cle":"lib","titre":"Désignation","largeur":"*","valeur":"{{ligne.libelle_html}}","html":true},{"cle":"qte","titre":"Qté","largeur":"15mm","valeur":"{{ligne.qte}}","alignement":"droite","format":"nombre:2","style":"montant","zero_vide":true,"condition":"NON Parametre(\"avancement\")"},{"cle":"u","titre":"U","largeur":"8mm","valeur":"{{ligne.unite}}","alignement":"centre","condition":"NON Parametre(\"avancement\")"},{"cle":"pu","titre":"PU HT","largeur":"19mm","valeur":"{{ligne.pu}}","alignement":"droite","format":"montant","style":"montant","condition":"Parametre(\"prix\") ET NON Parametre(\"avancement\")"},{"cle":"mt","titre":"Montant HT","largeur":"23mm","valeur":"{{ligne.montant}}","alignement":"droite","format":"montant","style":"montant","condition":"Parametre(\"prix\") ET NON Parametre(\"avancement\")","cumul":"=Si(ligne.compte_total; ligne.montant; Nul)"},{"cle":"amarche","titre":"Marché HT","largeur":"22mm","valeur":"{{ligne.avt_montant_marche}}","alignement":"droite","format":"montant","style":"montant","condition":"Parametre(\"avancement\")"},{"cle":"apct","titre":"% cumulé","largeur":"15mm","valeur":"{{ligne.avt_pct}}","alignement":"droite","format":"nombre:2","style":"montant","condition":"Parametre(\"avancement\")"},{"cle":"acumul","titre":"Cumul HT","largeur":"22mm","valeur":"{{ligne.avt_montant_cumul}}","alignement":"droite","format":"montant","style":"montant","condition":"Parametre(\"avancement\")","cumul":"=Si(ligne.compte_total; ligne.avt_montant_cumul; Nul)"},{"cle":"aprec","titre":"Précédent HT","largeur":"22mm","valeur":"{{ligne.avt_montant_precedent}}","alignement":"droite","format":"montant","style":"montant","condition":"Parametre(\"avancement\")","cumul":"=Si(ligne.compte_total; ligne.avt_montant_precedent; Nul)"},{"cle":"aperiode","titre":"Période HT","largeur":"22mm","valeur":"{{ligne.montant}}","alignement":"droite","format":"montant","style":"montant","condition":"Parametre(\"avancement\")","cumul":"=Si(ligne.compte_total; ligne.montant; Nul)"}],"gabarits":[{"condition":"ligne.composante ET NON Parametre(\"composantes\")","masquer":true},{"condition":"ligne.type = \"SAUT_PAGE\"","saut_page":true},{"condition":"ligne.type = \"IMAGE\"","masquer":true},{"condition":"ligne.type = \"SECTION\"","fond":"fond_section","style":"section","garder_avec_suivant":true,"bordures":{"haut":"fin","bas":"fin"},"cellules":[{"de":"num","a":"lib","valeur":"{{ligne.libelle_html}}","html":true},{"de":"qte","a":"aperiode","valeur":"=Si(Parametre(\"prix\"); ligne.montant; Nul)","alignement":"droite","format":"montant"}]},{"condition":"ligne.type = \"TITRE\"","fond":"fond_titre","style":"titre_ligne","garder_avec_suivant":true,"cellules":[{"colonne":"num","valeur":"{{ligne.numero}}"},{"de":"lib","a":"pu","valeur":"{{ligne.libelle_html}}","html":true,"retrait":"=ligne.niveau * 2"},{"de":"mt","a":"aperiode","valeur":"=Si(Parametre(\"prix\"); ligne.montant; Nul)","alignement":"droite","format":"montant"}]},{"condition":"ligne.type = \"TEXTE\"","cellules":[{"de":"lib","a":"aperiode","valeur":"{{ligne.libelle_html}}","html":true,"style":"discret","retrait":"=ligne.niveau * 2"}]},{"condition":"ligne.type = \"SOUS_TOTAL\" OU ligne.type = \"PIED\"","style":"sous_total","cellules":[{"de":"num","a":"pu","valeur":"{{ligne.libelle_html}}","html":true,"alignement":"droite"},{"de":"mt","a":"aperiode","valeur":"=Si(Parametre(\"prix\"); ligne.montant; Nul)","alignement":"droite","format":"montant"}]},{"condition":"ligne.composante","style":"composante","lie_au_precedent":true,"surcharges":{"lib":{"retrait":"=ligne.niveau * 2"}}},{"condition":"ligne.option OU ligne.pour_memoire","style":{"base":"normal","italique":true},"surcharges":{"lib":{"retrait":"=ligne.niveau * 2","valeur":"=Concat(ligne.libelle_html; Si(ligne.option; \" <i>(option)</i>\"; \"\"))","html":true},"mt":{"valeur":"=Si(ligne.pour_memoire; \"PM\"; ligne.montant)","alignement":"droite"}}},{"surcharges":{"lib":{"retrait":"=ligne.niveau * 2"}}}]}}'::jsonb, 'INTERNE', 0, TRUE, 'logibtp', 'logibtp'),
 ('TOTAUX_DOCUMENT', 'Totaux, TVA, échéances et accord', 'BLOC', NULL, NULL, '{}'::text[], '{"format_version":1,"code":"TOTAUX_DOCUMENT","libelle":"Totaux, TVA, échéances et accord","genre":"BLOC","parametres":[{"nom":"accord","defaut":false},{"nom":"lettres","defaut":false}],"contenu":{"type":"rangee","espacement":6,"marges":{"haut":3},"enfants":[{"type":"pile","largeur":"*","espacement":2,"enfants":[{"type":"champ","valeur":"{{textes.fin}}","html":true},{"type":"champ","valeur":"=Si(document.condition; \"Conditions de paiement : \" & document.condition.libelle; Nul)","style":"petit"},{"type":"pile","condition":"Compte(echeances) > 0","enfants":[{"type":"champ","valeur":"Échéancier","style":"gras"},{"type":"repete","collection":"echeances","contenu":{"type":"champ","valeur":"=Si(element.nature = \"RETENUE\"; \"Retenue de garantie\"; Si(element.date; \"Échéance du \" & Date(element.date); \"À la réception\")) & \" : \" & Monnaie(element.montant)","style":"petit"}}]},{"type":"champ","valeur":"=\"Arrêté à la somme de \" & EnLettres(totaux.net) & \".\"","style":"petit","condition":"bloc.lettres"}]},{"type":"pile","largeur":"75mm","espacement":0,"enfants":[{"type":"pile","cadre":"normal","marges":2,"enfants":[{"type":"repete","collection":"pied","contenu":{"type":"rangee","fond":"=Si(element.cle = \"NET\"; \"fond_total\"; Nul)","enfants":[{"type":"champ","valeur":"=Si(element.genre = \"total\"; Gras(element.libelle); element.libelle & Si(element.taux; \" \" & Si(element.genre = \"tva\"; \"\"; Nombre(element.taux; 2) & \" %\") ; \"\") & Si(element.base; \" sur \" & Montant(element.base); \"\"))","largeur":"*","style":"=Si(element.genre = \"total\"; \"gras\"; \"petit\")"},{"type":"champ","valeur":"{{element.montant}}","largeur":"28mm","format":"montant","alignement":"droite","style":"montant"}]}},{"type":"trait","trait":"fin"},{"type":"rangee","fond":"fond_total","marges":{"haut":0.5,"bas":0.5},"enfants":[{"type":"champ","valeur":"Net à payer","style":"gras","largeur":"*"},{"type":"champ","valeur":"{{totaux.net}}","format":"monnaie","style":"total","alignement":"droite","largeur":"35mm"}]}]},{"type":"pile","condition":"bloc.accord","marges":{"haut":2},"enfants":[{"type":"champ","valeur":"{{societe.mentions.accord}}","style":"petit"},{"type":"espace","hauteur":16}]}]}]}}'::jsonb, 'INTERNE', 0, TRUE, 'logibtp', 'logibtp'),
 ('MENTIONS_PAIEMENT', 'Mentions de paiement (pièces entre professionnels)', 'BLOC', NULL, NULL, '{}'::text[], '{"format_version":1,"code":"MENTIONS_PAIEMENT","libelle":"Mentions de paiement (pièces entre professionnels)","genre":"BLOC","parametres":[],"contenu":{"type":"champ","valeur":"=Joindre(\" \"; societe.mentions.penalites; societe.mentions.indemnite; societe.mentions.escompte; Si(societe.mentions.tva_debits; \"Option pour le paiement de la TVA d’après les débits.\"; Nul))","style":"mentions","marges":{"haut":2}}}'::jsonb, 'INTERNE', 0, TRUE, 'logibtp', 'logibtp'),
 ('MENTIONS_PARTICULIER', 'Mentions pour les particuliers (médiateur, rétractation)', 'BLOC', NULL, NULL, '{}'::text[], '{"format_version":1,"code":"MENTIONS_PARTICULIER","libelle":"Mentions pour les particuliers (médiateur, rétractation)","genre":"BLOC","parametres":[],"contenu":{"type":"pile","marges":{"haut":2},"enfants":[{"type":"champ","valeur":"=Si(societe.mentions.mediateur.nom; \"Médiateur de la consommation : \" & Joindre(\" – \"; societe.mentions.mediateur.nom; societe.mentions.mediateur.site); Nul)","style":"mentions"},{"type":"champ","valeur":"{{societe.mentions.retractation}}","style":"mentions"}]}}'::jsonb, 'INTERNE', 0, TRUE, 'logibtp', 'logibtp'),
 ('PIED_VENTES_ACHATS', 'Pied de page des ventes et achats (mentions obligatoires)', 'BLOC', NULL, NULL, '{}'::text[], '{"format_version":1,"code":"PIED_VENTES_ACHATS","libelle":"Pied de page des ventes et achats (mentions obligatoires)","genre":"BLOC","parametres":[],"contenu":{"type":"pile","cadre":{"haut":"fin"},"marges":{"haut":1},"enfants":[{"type":"champ","valeur":"=Joindre(\" – \"; societe.raison_sociale; Si(societe.forme_juridique; societe.forme_juridique & Si(societe.capital; \" au capital de \" & societe.capital; \"\"); Nul); societe.rcs; Si(societe.siret; \"SIRET \" & societe.siret; Nul); Si(societe.tva; \"TVA \" & societe.tva; Nul); Si(societe.naf; \"NAF \" & societe.naf; Nul))","style":"mentions","alignement":"centre"},{"type":"champ","valeur":"=Si(societe.mentions.decennale.assureur; \"Assurance décennale : \" & Joindre(\", \"; societe.mentions.decennale.assureur; societe.mentions.decennale.adresse; Si(societe.mentions.decennale.police; \"police \" & societe.mentions.decennale.police; Nul); Si(societe.mentions.decennale.couverture; \"couverture \" & societe.mentions.decennale.couverture; Nul)); Nul)","style":"mentions","alignement":"centre"},{"type":"rangee","enfants":[{"type":"champ","valeur":"{{document.type.libelle}} {{document.numero}}","style":"discret","largeur":"*"},{"type":"champ","valeur":"Page {{Page()}} / {{NbPages()}}","style":"discret","alignement":"droite","largeur":"30mm"}]}]}}'::jsonb, 'INTERNE', 0, TRUE, 'logibtp', 'logibtp'),
 ('PIED_INTERNE', 'Pied de page des documents internes (page, auteur, date)', 'BLOC', NULL, NULL, '{}'::text[], '{"format_version":1,"code":"PIED_INTERNE","libelle":"Pied de page des documents internes (page, auteur, date)","genre":"BLOC","parametres":[],"contenu":{"type":"rangee","cadre":{"haut":"fin"},"marges":{"haut":1},"enfants":[{"type":"champ","valeur":"Document interne – {{societe.raison_sociale}}","style":"discret","largeur":"*"},{"type":"champ","valeur":"Édité le {{Date(Aujourdhui())}}","style":"discret","alignement":"centre","largeur":"45mm"},{"type":"champ","valeur":"Page {{Page()}} / {{NbPages()}}","style":"discret","alignement":"droite","largeur":"30mm"}]}}'::jsonb, 'INTERNE', 0, TRUE, 'logibtp', 'logibtp'),
 ('FILIGRANE_STATUT', 'Filigrane selon le statut (provisoire, annulé)', 'BLOC', NULL, NULL, '{}'::text[], '{"format_version":1,"code":"FILIGRANE_STATUT","libelle":"Filigrane selon le statut (provisoire, annulé)","genre":"BLOC","parametres":[],"contenu":{"type":"absolu","x":30,"y":200,"largeur":220,"contenu":{"type":"champ","valeur":"=Si(document.statut.code = \"ANNULE\"; \"ANNULÉ\"; Si(NON document.verrouille; \"PROVISOIRE\"; Nul))","style":"filigrane","rotation":-35,"multiligne":"une"}}}'::jsonb, 'INTERNE', 0, TRUE, 'logibtp', 'logibtp'),
 ('RAPPEL_PAGES_SUIVANTES', 'Rappel du document en haut des pages suivantes', 'BLOC', NULL, NULL, '{}'::text[], '{"format_version":1,"code":"RAPPEL_PAGES_SUIVANTES","libelle":"Rappel du document en haut des pages suivantes","genre":"BLOC","parametres":[],"contenu":{"type":"rangee","cadre":{"bas":"fin"},"marges":{"bas":1},"enfants":[{"type":"champ","valeur":"{{societe.raison_sociale}}","style":"gras","largeur":"*"},{"type":"champ","valeur":"{{document.type.libelle}} {{document.numero}} du {{Date(document.date)}}","alignement":"droite","largeur":"*"}]}}'::jsonb, 'INTERNE', 0, TRUE, 'logibtp', 'logibtp'),
 ('SR_DOCUMENTS_MARCHE', 'Sous-rapport : commande et avenants du marché', 'RAPPORT', 'DOCUMENT', 'document', ARRAY['SOUS_RAPPORT']::text[], '{"format_version":1,"code":"SR_DOCUMENTS_MARCHE","libelle":"Sous-rapport : commande et avenants du marché","cible":"DOCUMENT","source":"document","bandes":[{"type":"CORPS","contenu":{"type":"pile","marges":{"haut":3},"enfants":[{"type":"champ","valeur":"Commande et avenants du marché","style":"sous_titre"},{"type":"tableau","collection":"elements","remplir":false,"report":false,"colonnes":[{"cle":"piece","titre":"Pièce","largeur":"30mm","valeur":"=Si(element.role = \"BASE\"; \"Commande\"; \"Avenant \" & element.rang)"},{"cle":"numero","titre":"N°","largeur":"30mm","valeur":"{{element.numero}}"},{"cle":"date","titre":"Date","largeur":"22mm","valeur":"{{Date(element.date)}}"},{"cle":"objet","titre":"Objet","largeur":"*","valeur":"{{element.objet}}"},{"cle":"mt","titre":"Montant HT","largeur":"28mm","valeur":"{{element.montant_ht}}","format":"montant","alignement":"droite","style":"montant"}]}]}}]}'::jsonb, 'INTERNE', 100, TRUE, 'logibtp', 'logibtp'),
